import jax
import jax.numpy as jnp
import flax.linen as nn
from jax import random
import optax
from typing import Any, Dict, Sequence

class DSConvDilatedBlock(nn.Module):
    d_model: int; kernel_size: int; dilation: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        # CRITICAL CHANGE: Use GELU, not ReLU
        h = nn.gelu(h)
        h = nn.Conv(features=self.d_model, kernel_size=(1,))(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

class RegressionHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x); z = nn.gelu(z); z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)
        return logits.squeeze(-1)

class MultiOutputHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x); z = nn.gelu(z); z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)
        return logits

class FidelityNet(nn.Module):
    d_output: int; task_type: str; d_model: int; num_blocks: int; dilations: Sequence[int]
    ds_kernel_size: int; motif_kernel_size: int; dropout_rate: float; head_intermediate_dim: int

    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.Dense(self.d_model, name="initial_dense")(x)
        h = nn.gelu(h); h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        for i in range(self.num_blocks):
            h = DSConvDilatedBlock(d_model=self.d_model, kernel_size=self.ds_kernel_size, dilation=self.dilations[i], dropout_rate=self.dropout_rate)(h, deterministic=deterministic)
        cnn_features = h

        mean_pooled = jnp.mean(cnn_features, axis=1)
        max_pooled = jnp.max(cnn_features, axis=1)
        main_path_features = jnp.concatenate([mean_pooled, max_pooled], axis=-1)

        motif_features = nn.Conv(features=self.d_model, kernel_size=(self.motif_kernel_size,), padding='SAME')(cnn_features)
        motif_features = nn.gelu(motif_features); motif_features = nn.Dropout(rate=self.dropout_rate)(motif_features, deterministic=deterministic)
        specialized_path_features = jnp.max(motif_features, axis=1)

        fused_features = jnp.concatenate([main_path_features, specialized_path_features], axis=-1)
        fused_features = nn.Dropout(rate=self.dropout_rate)(fused_features, deterministic=deterministic)
        z_fused = nn.LayerNorm()(fused_features)

        if self.task_type == "regression":
            logits = RegressionHead(d_output=self.d_output, dense_dim=self.head_intermediate_dim, dropout_rate=self.dropout_rate)(z_fused, deterministic=deterministic)
        else:
            logits = MultiOutputHead(d_output=self.d_output, dense_dim=self.head_intermediate_dim, dropout_rate=self.dropout_rate)(z_fused, deterministic=deterministic)
        return logits

class NetworkWrapper:
    def __init__(self, **kwargs): self.network = FidelityNet(**kwargs)
    def init(self, rng_key, dummy_input): return self.network.init(rng_key, dummy_input, deterministic=True)['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs={'dropout': rng_key} if not deterministic else None)

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model': 256, 'num_blocks': 5, 'dilations': [1,2,4,8,16],
        'ds_kernel_size': 7, 'motif_kernel_size': 5, 'dropout_rate': 0.1,
        'head_intermediate_dim': 128
    }

def create_network(hparams: Dict[str, Any]):
    network_params = [
        'd_output', 'task_type', 'd_model', 'num_blocks', 'dilations',
        'ds_kernel_size', 'motif_kernel_size', 'dropout_rate', 'head_intermediate_dim'
    ]
    network_hparams = {k: v for k, v in hparams.items() if k in network_params}
    return NetworkWrapper(**network_hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(learning_rate=learning_rate, weight_decay=0.01))

BASE_SEED = 7
